def backfill_error_codes(apps, schema_editor):
    """Catégorise les échecs historiques (le message d'erreur reste intact).

    Évite notamment que les anciens 403 / POL0001 d'Orange CI soient encore
    relancés automatiquement par `retry_failed_notifications`.
    """
    from apps.notifications.services.errors import classify_error

    Notification = apps.get_model("notifications", "Notification")
    qs = (
        Notification.objects.filter(status="failed", error_code="")
        .exclude(error_message="")
        .only("id", "error_message")
    )
    batch = []
    for notif in qs.iterator(chunk_size=500):
        notif.error_code = classify_error(notif.error_message)
        batch.append(notif)
        if len(batch) >= 500:
            Notification.objects.bulk_update(batch, ["error_code"])
            batch = []
    if batch:
        Notification.objects.bulk_update(batch, ["error_code"])


